import axios from "axios";
import { getTeamAbbr, round1, round3 } from "../utils/formatters";

// Static data files generated by GitHub Actions (served from same origin)
const BASE = import.meta.env.BASE_URL || "/";
const dataUrl = (path) => `${BASE}data/${path}`;

const staticFetch = (path) => axios.get(dataUrl(path)).then((r) => r.data);

// Normalize "Game Over" to "Final" — MLB API uses both for completed games
const normalizeStatus = (s) => s === "Game Over" ? "Final" : (s || "");

// MLB API sometimes marks isScoringPlay=false when runs score on mid-AB events
// (e.g. pickoff errors, wild pitches, passed balls during a strikeout).
// Check runners array as fallback.
const didRunScore = (play) =>
  play.about?.isScoringPlay ||
  (play.runners || []).some((r) => r.details?.isScoringEvent);

// Build description for plays where the scoring event is a mid-AB runner event
// (the result.description won't mention the run scoring in these cases)
const scoringDescription = (play) => {
  const desc = play.result?.description || "";
  if (play.about?.isScoringPlay) return desc;
  const scoredRunners = (play.runners || [])
    .filter((r) => r.details?.isScoringEvent)
    .map((r) => r.details?.runner?.fullName || "");
  if (!scoredRunners.length) return desc;
  const event = (play.runners || [])
    .find((r) => r.details?.isScoringEvent)?.details?.event || "";
  const eventDesc = event.replace(/_/g, " ");
  const scored = scoredRunners.join(", ");
  return desc
    ? `${scored} scores on ${eventDesc.toLowerCase()}. ${desc}`
    : `${scored} scores on ${eventDesc.toLowerCase()}.`;
};

// MLB Stats API called directly from browser (no backend needed, free & fast)
const mlbApi = axios.create({
  baseURL: "https://statsapi.mlb.com/api/v1",
  timeout: 15000,
});

// ---- Static data (generated daily) ----
export const fetchRoster = async (teamId) => {
  const season = new Date().getFullYear();
  const resp = await mlbApi.get(`/teams/${teamId}/roster`, {
    params: { rosterType: "active", season },
  });
  return (resp.data.roster || []).map((entry) => {
    const p = entry.person || {};
    const pos = entry.position || {};
    return {
      id: p.id,
      fullName: p.fullName || "",
      jerseyNumber: entry.jerseyNumber || "",
      position: {
        code: pos.code || "",
        name: pos.name || "",
        type: pos.type || "",
        abbreviation: pos.abbreviation || "",
      },
      status: entry.status?.description || "Active",
      photoUrl: `https://img.mlbstatic.com/mlb-photos/image/upload/d_people:generic:headshot:67:current.png/w_213,q_auto:best/v1/people/${p.id}/headshot/67/current`,
    };
  });
};

export const fetchSchedule = (teamId) => staticFetch(`teams/${getTeamAbbr(teamId)}/schedule.json`);

// Fetch recent + upcoming schedule from live MLB API to supplement static data
export const fetchLiveSchedule = async (teamId) => {
  try {
    const now = new Date();
    const start = new Date(now);
    start.setDate(start.getDate() - 7); // last 7 days
    const end = new Date(now);
    end.setDate(end.getDate() + 1);
    const fmt = (d) => d.toISOString().split("T")[0];
    const resp = await mlbApi.get("/schedule", {
      params: { sportId: 1, teamId, startDate: fmt(start), endDate: fmt(end), hydrate: "team,linescore", gameType: "R" },
    });
    const games = [];
    for (const date of resp.data?.dates || []) {
      for (const g of date.games || []) {
        games.push({
          gamePk: g.gamePk,
          status: normalizeStatus(g.status?.detailedState),
          awayScore: g.teams?.away?.score ?? null,
          homeScore: g.teams?.home?.score ?? null,
        });
      }
    }
    return games;
  } catch { return []; }
};

export const fetchStandings = async () => {
  // Fetch live from MLB API for freshest standings
  try {
    const season = new Date().getFullYear();
    const resp = await mlbApi.get("/standings", {
      params: {
        season, sportId: 1, leagueId: "103,104",
        hydrate: "team,league,division,records",
      },
    });
    const divisions = [];
    for (const record of resp.data?.records || []) {
      const div = record.division || {};
      const lg = record.league || {};
      const teams = (record.teamRecords || []).map((tr) => {
        const t = tr.team || {};
        // splitRecords holds home/away/lastTen/etc. as { wins, losses, type, pct }
        const splits = tr.records?.splitRecords || [];
        const getSplit = (type) => splits.find((s) => s.type === type) || { wins: 0, losses: 0 };
        const home = getSplit("home");
        const away = getSplit("away");
        const lastTen = getSplit("lastTen");
        return {
          id: t.id,
          name: t.name || "",
          abbreviation: t.abbreviation || "",
          wins: tr.wins || 0,
          losses: tr.losses || 0,
          winPct: tr.winningPercentage || ".000",
          gamesBack: tr.gamesBack || "-",
          wildCardGamesBack: tr.wildCardGamesBack || "-",
          leagueGamesBack: tr.leagueGamesBack || "-",
          divisionRank: tr.divisionRank ? Number(tr.divisionRank) : null,
          leagueRank: tr.leagueRank ? Number(tr.leagueRank) : null,
          wildCardRank: tr.wildCardRank ? Number(tr.wildCardRank) : null,
          streakCode: tr.streak?.streakCode || "",
          runsScored: tr.runsScored ?? 0,
          runsAllowed: tr.runsAllowed ?? 0,
          runDifferential: tr.runDifferential ?? 0,
          clinchIndicator: tr.clinchIndicator || "",
          eliminationNumber: tr.eliminationNumber || "",
          homeRecord: `${home.wins}-${home.losses}`,
          awayRecord: `${away.wins}-${away.losses}`,
          lastTenRecord: `${lastTen.wins}-${lastTen.losses}`,
          leagueId: lg.id,
          leagueName: lg.name || "",
          divisionId: div.id,
          divisionName: div.name || "",
          logoUrl: `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${t.id}.svg`,
        };
      });
      divisions.push({
        divisionId: div.id,
        divisionName: div.name || "",
        leagueId: lg.id,
        leagueName: lg.name || "",
        teams,
      });
    }
    return divisions;
  } catch {
    // Fallback to static data if API fails
    return staticFetch("standings.json");
  }
};



export const fetchPlayerStats = async (playerId) => {
  // Try static pre-generated data first (our roster players — most comprehensive)
  try {
    const data = await staticFetch(`players/${playerId}/info.json`);
    if (data?.detail?.id) return { ...data, hasFullData: true };
  } catch { /* expected fallback */ }

  // Fallback: MLB API for any player (opponents, etc.)
  const season = new Date().getFullYear();
  const [detailResp, hittingResp, pitchingResp] = await Promise.all([
    mlbApi.get(`/people/${playerId}`, { params: { hydrate: "currentTeam" } }),
    mlbApi.get(`/people/${playerId}/stats`, { params: { stats: "season", season, group: "hitting" } }).catch(() => ({})),
    mlbApi.get(`/people/${playerId}/stats`, { params: { stats: "season", season, group: "pitching" } }).catch(() => ({})),
  ]);

  const p = detailResp.data?.people?.[0];
  if (!p) throw new Error("Player not found");

  const isPitcher = p.primaryPosition?.abbreviation === "P";
  const group = isPitcher ? "pitching" : "hitting";
  const statsResp = isPitcher ? pitchingResp : hittingResp;
  const splits = statsResp.data?.stats?.[0]?.splits || [];
  const currentStats = splits[0]?.stat || {};

  // Try previous season if no current stats
  let prevStats = {};
  if (!Object.keys(currentStats).length) {
    try {
      const prev = await mlbApi.get(`/people/${playerId}/stats`, {
        params: { stats: "season", season: season - 1, group },
      });
      const prevSplits = prev.data?.stats?.[0]?.splits || [];
      prevStats = prevSplits[0]?.stat || {};
    } catch { /* expected fallback */ }
  }

  return {
    detail: {
      id: p.id,
      fullName: p.fullName || "",
      firstName: p.firstName || "",
      lastName: p.lastName || "",
      primaryNumber: p.primaryNumber || "",
      birthDate: p.birthDate || "",
      age: p.currentAge,
      height: p.height || "",
      weight: p.weight,
      batSide: p.batSide?.code || "",
      pitchHand: p.pitchHand?.code || "",
      primaryPosition: p.primaryPosition?.abbreviation || "",
      mlbDebutDate: p.mlbDebutDate || "",
      currentTeam: p.currentTeam?.name || "",
      currentTeamId: p.currentTeam?.id || null,
      photoUrl: `https://img.mlbstatic.com/mlb-photos/image/upload/d_people:generic:headshot:67:current.png/w_213,q_auto:best/v1/people/${p.id}/headshot/67/current`,
    },
    stats: {
      season,
      group,
      stats: currentStats,
      prevSeason: season - 1,
      prevStats,
    },
  };
};

